import React, { useState, useEffect, useRef } from 'react';
import { MapContainer, TileLayer, Marker,Polyline, Popup, useMapEvents } from 'react-leaflet';
import L from 'leaflet';
import VehicleIcon from './VehicleIcon';
import StationIcon from './StationIcon';

const MapClickHandler = ({ onMapClick }) => {
  useMapEvents({
    click: (e) => {
      if (e && e.latlng) {
        const { lat, lng } = e.latlng;
        onMapClick({ lat, lng });
      } else {
        console.error("LatLng is undefined", e);
      }
    },
  });
  return null;
};

const getOffset = (index) => {
  const offset = 0.0002; // Adjust this value for better spacing
  return {
    lat: (index % 10) * offset,
    lng: Math.floor(index / 10) * offset
  };
};

const interpolatePosition = (start, end, fraction) => {
  return {
    lat: start.lat + (end.lat - start.lat) * fraction,
    lng: start.lng + (end.lng - start.lng) * fraction
  };
};

const animateVehicle = (start, end, duration, updatePosition) => {
  const startTime = performance.now();

  function step(currentTime) {
    const elapsed = currentTime - startTime;
    const fraction = Math.min(elapsed / duration, 1);
    const position = interpolatePosition(start, end, fraction);

    updatePosition(position);

    if (fraction < 1) {
      requestAnimationFrame(step);
    }
  }

  requestAnimationFrame(step);
};

const getVehicleColor = (id) => {
  const colors = [
    'blue',    // 0
    'red',     // 1
    'green',   // 2
    'purple',  // 3
    'orange',  // 4
    'cyan',    // 5
    'magenta', // 6
    'brown',   // 7
    'pink',    // 8
    'yellow'   // 9
  ];
  return colors[id % colors.length]; // Associe une couleur basée sur l'ID du véhicule
};

const MapComponent = React.memo(({ vehicles, stations, onMapClick }) => {
  const [vehicleTrails, setVehicleTrails] = useState({});

  useEffect(() => {
    const initialPositions = vehicles.reduce((acc, vehicle) => {
      if (vehicle.previousLocation && vehicle.location) {
        acc[vehicle.id] = {
          points: [[vehicle.previousLocation.lat, vehicle.previousLocation.lng]],
          end: [vehicle.location.lat, vehicle.location.lng],
          color: getVehicleColor(vehicle.id)
        };
      }
      return acc;
    }, {});

    setVehicleTrails(initialPositions);

    const updateVehiclePositions = () => {
      setVehicleTrails((prevTrails) => {
        const newTrails = {};

        for (let id in prevTrails) {
          const { points, end, color } = prevTrails[id];

          // Vérifiez si les coordonnées de start et end sont définies
          if (!points.length || !end) {
            console.error('Points or end location is undefined for vehicle', id);
            continue;
          }

          const lastPoint = points[points.length - 1];
          const progress = (Date.now() % 10000) / 10000; // Ajustez le dénominateur pour modifier la vitesse
          const newLat = lastPoint[0] + (end[0] - lastPoint[0]) * progress;
          const newLng = lastPoint[1] + (end[1] - lastPoint[1]) * progress;

          if (progress >= 1) {
            // Si le véhicule atteint la destination, ajoutez le point final et mettez à jour le prochain segment
            newTrails[id] = {
              points: [...points, end],
              end: end,
              color: color
            };
          } else {
            // Continuez à déplacer le véhicule
            newTrails[id] = {
              points: [...points.slice(0, -1), [newLat, newLng]], // Ajoutez la nouvelle position
              end: end,
              color: color
            };
          }
        }

        return newTrails;
      });
    };

    const intervalId = setInterval(updateVehiclePositions, 100); // Ajustez l'intervalle pour contrôler la fluidité du mouvement

    return () => clearInterval(intervalId);
  }, [vehicles]);

  // Styles pour les lignes
  const lineStyle = (color) => ({
    color: color,
    weight: 5,
    opacity: 0.7
  });

  return (
    <MapContainer center={[-37.814, 144.96332]} zoom={13} style={{ height: '100%', width: '100%' }}>
      <TileLayer
        url="https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png"
        attribution="&copy; <a href='https://www.openstreetmap.org/copyright'>OpenStreetMap</a> contributors"
      />
      <MapClickHandler onMapClick={onMapClick} />
      {vehicles.map((vehicle) => {
        const position = vehicleTrails[vehicle.id]?.points.slice(-1)[0] || vehicle.location;
        return (
          <Marker key={vehicle.id} position={position} icon={VehicleIcon}>
            <Popup>
              <div>
                <h3>{vehicle.name}</h3>
                <p>Capacity: {vehicle.battery_capacity}</p>
                <p>Battery: {vehicle.battery}</p>
                <p>Consumption: {vehicle.consumption}</p>
              </div>
            </Popup>
          </Marker>
        );
      })}
      {stations.map((station, index) => {
        const offset = getOffset(index + vehicles.length);
        const position = [station.location.lat + offset.lat, station.location.lng + offset.lng];
        return (
          <Marker key={station.id} position={position} icon={StationIcon}>
            <Popup>
              <div>
                <h3>{station.name}</h3>
                <p>Price per kwh: {station.price_per_kwh}</p>
                <p>Charging speed: {station.charging_speed}</p>
                <p>Buy price per kwh: {station.buy_price_per_kwh}</p>
                <p>Discharging speed: {station.discharging_speed}</p>
              </div>
            </Popup>
          </Marker>
        );
      })}
      {Object.values(vehicleTrails).map((trail, index) => (
        <Polyline key={index} positions={trail.points} pathOptions={lineStyle(trail.color)} />
      ))}
    </MapContainer>
  );
});

export default MapComponent;
